    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Check if a position is valid
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Check if the goal is reached
    def is_goal(r, c):
        return (r, c) == goal

    # DFS to find a path from start to goal
    def dfs(r, c, path):
        if is_goal(r, c):
            return path + [(r, c)]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                result = dfs(nr, nc, path + [(r, c)])
                if result:
                    return result
        return []

    # Start DFS from the start position
    path = [start]
    return dfs(start[0], start[1], path)
