from collections import deque

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Check if a cell is valid
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) != start

    # Backtrack to reconstruct the path
    def backtrack(path, current):
        if current == start:
            return path
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if (r, c) in path:
                result = backtrack(path, (r, c))
                if result:
                    return result
        return []

    # DFS to find a path
    def dfs(current, path):
        if current == goal:
            return path + [current]
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if is_valid(r, c):
                result = dfs((r, c), path + [current])
                if result:
                    return result
        return []

    # Try to find a path using DFS
    path = dfs(start, [])
    if path:
        return path
    return []
